        "target": {
          "description": "Element ref from snapshot (e.g., 'e39')",
          "title": "Target",
          "type": "string"
        },
        "doubleClick": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "default": false,
          "title": "Doubleclick"
        },
        "button": {
          "default": "left",
          "enum": [
            "left",
            "right",
            "middle"
          ],
          "title": "Button",
          "type": "string"
        }
      },
      "required": [
        "target"
      ],
      "title": "ClickArgs",
      "type": "object"
    }
  },
  {
    "name": "browser_type",
    "description": "\n    Type into a SINGLE input field.\n    RULE: If multiple fields need filling, use browser_fill_form instead.\n    ",
    "parameters": {
      "additionalProperties": false,
      "description": "Type into a SINGLE input field.\nRULE: If multiple fields need filling, use browser_fill_form instead.",
      "properties": {
        "target": {
          "description": "Element ref from snapshot",
          "title": "Target",
          "type": "string"
        },
        "text": {
          "description": "Text to type",
          "title": "Text",
          "type": "string"
        },
        "submit": {
          "anyOf": [
            {
              "type": "boolean"
            },
            {
              "type": "null"
            }
          ],
          "default": false,
